// n8n Code Node
// Mode: Run Once for All Items

const rows = $input.all().map(item => item.json);

const cleaned = [];
const seenEmails = new Set();
const seenPhones = new Set();

const stats = {
  totalRows: rows.length,
  emptyRows: 0,
  invalidEmails: 0,
  invalidPhones: 0,
  duplicateRows: 0,
  invalidDates: 0
};

// Find columns even if headers contain extra spaces
function getValue(row, column) {
  const key = Object.keys(row).find(
    k => k.trim().toLowerCase() === column.toLowerCase()
  );
  return key ? row[key] : "";
}

// Clean spaces and capitalization
function properCase(value) {
  return String(value ?? "")
    .trim()
    .replace(/\s+/g, " ")
    .toLowerCase()
    .replace(/\b[a-z]/g, c => c.toUpperCase());
}

// Validate email
function validEmail(email) {
  return /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(email);
}

// Normalize Bangladesh mobile number
function normalizePhone(value) {
  let phone = String(value ?? "").trim().replace(/\D/g, "");

  if (phone.startsWith("00880")) {
    phone = phone.slice(2);
  }

  if (phone.startsWith("8801")) {
    phone = "0" + phone.slice(3);
  }

  return phone;
}

function validPhone(phone) {
  return /^01[3-9]\d{8}$/.test(phone);
}

// Validate a calendar date
function makeDate(year, month, day) {
  const d = new Date(Date.UTC(year, month - 1, day));

  if (
    d.getUTCFullYear() !== year ||
    d.getUTCMonth() !== month - 1 ||
    d.getUTCDate() !== day
  ) return "";

  return `${year}-${String(month).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

// Convert Excel dates and common date formats
function normalizeDate(value) {
  if (value === null || value === undefined || value === "") {
    return "";
  }

  // Excel serial date
  if (typeof value === "number" && value > 0) {
    const d = new Date(Date.UTC(1899, 11, 30) + value * 86400000);
    return makeDate(
      d.getUTCFullYear(),
      d.getUTCMonth() + 1,
      d.getUTCDate()
    );
  }

  const s = String(value).trim();
  let m;

  // YYYY-MM-DD
  m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})$/);
  if (m) return makeDate(+m[1], +m[2], +m[3]);

  // DD-MM-YYYY (e.g. 03-05-2025 = 3 May)
  m = s.match(/^(\d{1,2})-(\d{1,2})-(\d{4})$/);
  if (m) return makeDate(+m[3], +m[2], +m[1]);

  // MM/DD/YYYY (e.g. 01/05/2025 = January 5)
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return makeDate(+m[3], +m[1], +m[2]);

  return "";
}

for (const row of rows) {
  const name = properCase(getValue(row, "Full Name"));
  const email = String(getValue(row, "Email") ?? "")
    .trim().toLowerCase();
  const phone = normalizePhone(getValue(row, "Phone"));
  const city = properCase(getValue(row, "City"));
  const rawDate = getValue(row, "Date");
  const date = normalizeDate(rawDate);

  // Remove completely empty rows
  if (![name, email, phone, city, rawDate].some(v => String(v ?? "").trim() !== "")) {
    stats.emptyRows++;
    continue;
  }

  // Validate email
  if (!validEmail(email)) {
    stats.invalidEmails++;
    continue;
  }

  // Validate phone
  if (!validPhone(phone)) {
    stats.invalidPhones++;
    continue;
  }

  // Remove duplicate email OR phone
  if (seenEmails.has(email) || seenPhones.has(phone)) {
    stats.duplicateRows++;
    continue;
  }

  seenEmails.add(email);
  seenPhones.add(phone);

  if (rawDate !== "" && !date) {
    stats.invalidDates++;
  }

  cleaned.push({
    "Customer ID": `CUST-${String(cleaned.length + 1).padStart(4, "0")}`,
    "Full Name": name,
    "Email": email,
    "Phone": phone,
    "City": city,
    "Date": date
  });
}

// Return customers plus one summary record.
// We will separate them in the next step.
const customerItems = cleaned.map(row => ({
  json: { ...row, _recordType: "customer" }
}));

const summary = {
  _recordType: "summary",
  "Total Rows Imported": stats.totalRows,
  "Empty Rows Removed": stats.emptyRows,
  "Invalid Emails Removed": stats.invalidEmails,
  "Invalid Phones Removed": stats.invalidPhones,
  "Duplicate Rows Removed": stats.duplicateRows,
  "Invalid Dates Blank": stats.invalidDates,
  "Final Row Count": cleaned.length
};

return [
  ...customerItems,
  { json: summary }
];
